-- Banco oficial Intermedio (90). Dificultad medium = Intermedio en la app (4 pts).
-- No hay columna de tiempo: la app ya usa 15 segundos para todas las trivias.
-- El archivo fuente no trae tema; se guarda el lote en category.
on conflict (code) where code is not null do nothing;

update public.pulse_trivia_questions
set status = 'disabled',
    review_note = 'fuera del banco Intermedio oficial'
where difficulty = 'medium'
  and status = 'active'
  and id not like 'trv_int_%';
